-- 付費好友與全服唯一徽章（成就設計 V2 §7.2、§7.3）。數字由 Harbor 的徽章統計提供（paidInvites、越線時間）。
ALTER TABLE badge_qualifications ADD COLUMN paid_invites INTEGER NOT NULL DEFAULT 0 CHECK(paid_invites>=0);
ALTER TABLE badge_qualifications ADD COLUMN paid_invites_100_at INTEGER;
ALTER TABLE badge_qualifications ADD COLUMN starlight_at INTEGER;
-- 全服唯一（first_ 開頭、不是 _pioneer 結尾）一枚只有一個持有人，撤銷了也佔著位子（撤銷不順延）。
CREATE UNIQUE INDEX community_awards_first_holder ON community_awards(badge) WHERE badge LIKE 'first\_%' ESCAPE '\' AND badge NOT LIKE '%\_pioneer' ESCAPE '\';

